'use client';
import {invoiceResponse} from '@/lib/invoice-response';
import {useEffect,useRef,useState} from 'react';
import {guestFields,isIdentityField} from '@/lib/guests';
import {hotelClient,hotelRpc,usd} from '@/lib/pilot';
import {prepareInvoiceIssue,readInvoiceIssueReceipt} from '@/lib/invoice-issue';
import {savePendingInvoice,loadPendingInvoice,clearPendingInvoice} from '@/lib/invoice-pending';
import {readInvoiceSources} from '@/lib/invoice-sources';
import {InvoiceRecipientCopy} from '@/components/invoice-recipient-copy';
import {InvoiceRecovery} from '@/components/invoice-recovery';
type Props={tenant:string;property:string;reservation:string;actor:string;disabled:boolean;preview:ReturnType<typeof readInvoiceSources>};
export function InvoiceIssueForm(props:Props){return <Issue key={[props.tenant,props.property,props.reservation,props.actor,props.preview.source_hash].join(':')} {...props}/>;}
function Issue({disabled,preview,...scope}:Props){
 const [review,setReview]=useState<ReturnType<typeof prepareInvoiceIssue>|null>(null),[busy,setBusy]=useState(false),[error,setError]=useState(''),[message,setMessage]=useState(''),[revision,setRevision]=useState(0);const alive=useRef(false),lock=useRef(false),formRef=useRef<HTMLFormElement>(null),editVersion=useRef(0);
 useEffect(()=>{alive.current=true;return()=>{alive.current=false;};},[]);
 function prepare(form:FormData){editVersion.current++;try{if(loadPendingInvoice(sessionStorage,scope))throw Error('Resolve the pending invoice request before issuing another invoice.');const selections=preview.lines.flatMap((line,index)=>{const value=String(form.get('charge_'+index)||'0');if(!/^\d+(\.\d{1,2})?$/.test(value))throw Error('Enter charge amounts with at most two decimal places.');const [whole,fraction='']=value.split('.'),amount=BigInt(whole)*BigInt(100)+BigInt(fraction.padEnd(2,'0'));return amount===BigInt(0)?[]:[{source_key:line.source_key,amount_minor:amount.toString()}];});setReview(prepareInvoiceIssue(scope,crypto.randomUUID(),{schema_version:1,tenant_id:scope.tenant,property_id:scope.property,reservation_id:scope.reservation,actor_id:scope.actor,currency:'USD',...preview},form,selections));setError('');}catch(cause){setError(cause instanceof Error?cause.message:'Review invoice details.');}}
 async function issue(){if(lock.current||disabled||!review)return;lock.current=true;setBusy(true);setError('');try{
  const user=await invoiceResponse(hotelClient().auth.getUser());if(user.error||user.data.user?.id!==scope.actor)throw Error('Sign-in changed. Reopen this stay.');if(!alive.current)return;
  if(loadPendingInvoice(sessionStorage,scope))throw Error('Resolve the pending invoice request first.');
  savePendingInvoice(sessionStorage,scope,{...scope,request:review.args.p_request,amount_minor:review.amount_minor,due_on:review.args.p_due_on});setRevision(v=>v+1);
  const result=await invoiceResponse(hotelRpc<unknown>('issue_invoice',review.args)),again=await invoiceResponse(hotelClient().auth.getUser());if(again.error||again.data.user?.id!==scope.actor)throw Error('Sign-in changed. Recover the invoice after signing in.');if(!alive.current)return;
  const receipt=readInvoiceIssueReceipt(result,review);clearPendingInvoice(sessionStorage,scope,review.args.p_request);setReview(null);setMessage('Invoice '+receipt.number+' issued. Load issued invoices to open it.');
 }catch(cause){if(alive.current)setError(cause instanceof Error?cause.message:'Submission interrupted. Check invoice recovery.');}finally{lock.current=false;if(alive.current){setBusy(false);setRevision(v=>v+1);}}}
 return <section className="pilot-settings"><h3>Issue invoice</h3>{!message&&<form ref={formRef} onChange={()=>{editVersion.current++;}} onSubmit={e=>{e.preventDefault();prepare(new FormData(e.currentTarget));}}><fieldset disabled={busy||disabled||!!review}><label className="field">Due date<input type="date" name="due_on" required/></label>{[['issuer_','Issuer'],['billing_','Bill to']].map(([prefix,label])=><fieldset key={prefix}><legend>{label}</legend>{prefix==='billing_'&&<InvoiceRecipientCopy {...scope} getEditVersion={()=>editVersion.current} disabled={busy||disabled||!!review} onCopy={data=>{const form=formRef.current;if(!form)return;for(const [key,value] of Object.entries(data)){const input=form.elements.namedItem('billing_'+key);if(input instanceof HTMLInputElement)input.value=value??'';}}}/>}{guestFields.filter(([key])=>key!=='display_name'&&!isIdentityField(key)).map(([key,label,max])=><label className="field" key={key}>{label}<input name={prefix+key} maxLength={max}/></label>)}</fieldset>)}{preview.lines.filter(line=>line.available_minor!=='0').map(line=>{const index=preview.lines.indexOf(line),digits=line.available_minor.padStart(3,'0');return <label className="field" key={line.source_key}>{line.description} (USD)<input name={'charge_'+index} inputMode="decimal" defaultValue={digits.slice(0,-2)+'.'+digits.slice(-2)}/></label>;})}<button disabled={busy||disabled||!!review}>Review invoice</button></fieldset></form>}{review&&<section><p>Issuer: {review.args.p_issuer.legal_name||review.args.p_issuer.company_name}</p><p>Bill to: {review.args.p_billing_party.legal_name||review.args.p_billing_party.company_name}</p><p>Due {review.args.p_due_on} · Total {usd(Number(review.amount_minor))}</p><table className="pilot-table"><caption>Reviewed invoice charges · USD</caption><thead><tr><th>Charge</th><th>Amount</th></tr></thead><tbody>{review.args.p_lines.map(line=><tr key={line.source_key}><td>{preview.lines.find(source=>source.source_key===line.source_key)?.description}</td><td>{usd(Number(line.amount_minor))}</td></tr>)}</tbody></table><button disabled={busy||disabled} onClick={()=>void issue()}>Confirm and issue invoice</button><button disabled={busy||disabled} onClick={()=>setReview(null)}>Edit review</button></section>}{error&&<p role="alert">{error}</p>}{message&&<p role="status">{message}</p>}<InvoiceRecovery key={revision} {...scope} disabled={busy||disabled}/></section>;
}
